import{_ as e,o,c as l,ak as i}from"./chunks/framework.DKi5cyCJ.js";const h=JSON.parse('{"title":"I2C 总线","description":"开漏上拉、起始停止、ACK、时钟拉伸与总线卡死恢复","frontmatter":{"title":"I2C 总线","description":"开漏上拉、起始停止、ACK、时钟拉伸与总线卡死恢复","date":"2026-10-20T00:00:00.000Z"},"headers":[],"relativePath":"pages/blog/2026-10-20-I2C总线.md","filePath":"pages/blog/2026-10-20-I2C总线.md"}'),s={name:"pages/blog/2026-10-20-I2C总线.md"};function d(t,a,c,r,n,p){return o(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="i2c-开漏、时序与卡死恢复" tabindex="-1">I2C：开漏、时序与卡死恢复 <a class="header-anchor" href="#i2c-开漏、时序与卡死恢复" aria-label="Permalink to &quot;I2C：开漏、时序与卡死恢复&quot;">​</a></h1><blockquote><p>系列目录：<a href="/pages/blog/2026-10-20-嵌入式驱动面试手册.html">嵌入式驱动面试手册</a> · <a href="/demos/i2c-timing.html" target="_blank">时序动画</a></p></blockquote><div class="blog-demo-frame"><iframe src="/demos/i2c-timing.html?embed=1" title="I2C 时序动态演示" loading="lazy"></iframe></div><p>I2C（原理图里常写成 IIC）是两线开漏总线：SDA、SCL。高电平靠上拉，设备只能拉低。空闲时两线都是高。SCL 为高时 SDA 必须稳定：下降是起始，上升是停止。数据在 SCL 为低时改变，在 SCL 为高时被采样。</p><p>7 位地址放在地址字节的高 7 位，最低位是方向：0 写，1 读。地址 <code>0x50</code> 的写字节是 <code>0xA0</code>，读字节是 <code>0xA1</code>。不要把 <code>0xA0</code> 再左移一次。</p><h2 id="上拉" tabindex="-1">上拉 <a class="header-anchor" href="#上拉" aria-label="Permalink to &quot;上拉&quot;">​</a></h2><p>标准模式灌电流 3 mA、输出低电平不超过 0.4 V 时：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Rp(min) = (VDD - 0.4) / 0.003</span></span></code></pre></div><p>3.3 V 时约 967 Ω。电阻太大，上升时间会超过模式上限（标准模式 1000 ns，快速模式 300 ns）。100 kHz、总线不长时常用 4.7 kΩ；400 kHz 或线较长时用 2.2 kΩ 或 1 kΩ。引脚必须开漏，推挽输出高会和从机对灌。</p><h2 id="一次读" tabindex="-1">一次读 <a class="header-anchor" href="#一次读" aria-label="Permalink to &quot;一次读&quot;">​</a></h2><div class="blog-flow"><div class="blog-flow-row"><div class="blog-flow-node">起始</div><div class="blog-flow-arrow">→</div><div class="blog-flow-node">地址 + 写</div><div class="blog-flow-arrow">→</div><div class="blog-flow-node">寄存器地址</div><div class="blog-flow-arrow">→</div><div class="blog-flow-node accent">重复起始</div><div class="blog-flow-arrow">→</div><div class="blog-flow-node">地址 + 读</div><div class="blog-flow-arrow">→</div><div class="blog-flow-node">数据，最后 NACK</div></div></div><p>中间不要插入停止，否则从机的地址指针会丢。写的时候 ACK 由从机拉低；读的时候 ACK 由主机拉低，最后一字节主机保持 SDA 为高，发出 NACK。</p><p>从机可以在 SCL 为低时继续拉住时钟，这是时钟拉伸。软件模拟必须等 SCL 真的变高再采样。EEPROM 页写之后有几毫秒内部周期，期间会 NACK，要轮询应答或延时。</p><h2 id="软件模拟要点" tabindex="-1">软件模拟要点 <a class="header-anchor" href="#软件模拟要点" aria-label="Permalink to &quot;软件模拟要点&quot;">​</a></h2><p>写 1 是释放总线，不是推挽输出高。发送完 8 位后释放 SDA，把第 9 个时钟让给 ACK。</p><p>总线卡死的典型情况是主机复位时从机还拉着 SDA。把 SCL 当 GPIO，最多给 9 个脉冲，直到 SDA 变高，再补一个停止，然后重新初始化外设。</p><p>STM32F4、PCLK 42 MHz、标准模式 100 kHz：CCR 约 210，TRISE = 43。F7/H7 用 TIMINGR，不能抄 CCR。</p><p>全部 NACK 时先核对地址有没有多移一次、写读位、以及地址引脚电平。</p><p><a href="/pages/blog/2026-10-20-嵌入式驱动面试手册.html">返回目录</a></p>',19)])])}const C=e(s,[["render",d]]);export{h as __pageData,C as default};
